import kotlinx.html.*

fun FlowContent.card() {
    div {
        attributes["data-on:click"] = "@clipbord('x')"
        attributes["data-persist"] = ""
    }
}

import kotlinx.html.*

fun FlowContent.card(name: String, handler: String) {
    div {
        attributes[name] = "@clipbord('x')"
        attributes["data-on:click"] = handler
    }
}
